<script setup>
import { onMounted, ref } from 'vue'
import { showToast, showConfirmDialog } from 'vant'
import { useRoute, useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
const route = useRoute(); const router = useRouter(); const authStore = useAuthStore()
const loading = ref(false); const data = ref({ order: {}, items: [], tracks: [], review: [] }); const completing = ref(false); const reviewVisible = ref(false); const reviewSubmitting = ref(false); const rating = ref(5); const reviewContent = ref('')
const statusMap = { 1: '待接单', 2: '已接待', 3: '已完成' }
async function load() { loading.value = true; try { const response = await fetch(`/api/shop/orders/get/${route.params.id}`, { headers: { Authorization: `Bearer ${authStore.token}` } }); const result = await response.json(); if (!response.ok || result.code !== 0) throw new Error(result.message || '订单加载失败'); data.value = result.data; if (route.query.review === '1' && (data.value.canReview === true || Number(data.value.canReview) === 1)) reviewVisible.value = true } catch (error) { showToast(error.message || '订单加载失败') } finally { loading.value = false } }
async function accept() { completing.value = true; try { const response = await fetch(`/api/shop/manage/orders/accept/${route.params.id}`, { method: 'PUT', headers: { Authorization: `Bearer ${authStore.token}` } }); const result = await response.json(); if (!response.ok || result.code !== 0) throw new Error(result.message || '接单失败'); showToast('已确认接单'); await load() } catch (error) { showToast(error.message || '接单失败') } finally { completing.value = false } }
async function complete() { try { await showConfirmDialog({ title: '确认完成', message: '确认对方已完成服务吗？' }); completing.value = true; const response = await fetch(`/api/shop/orders/complete/${route.params.id}`, { method: 'PUT', headers: { Authorization: `Bearer ${authStore.token}` } }); const result = await response.json(); if (!response.ok || result.code !== 0) throw new Error(result.message || '操作失败'); await load(); reviewVisible.value = Boolean(data.value.canReview) } catch (error) { if (error) showToast(error.message || '操作已取消') } finally { completing.value = false } }
function skipReview() { reviewVisible.value = false }
async function submitReview() { reviewSubmitting.value = true; try { const response = await fetch(`/api/shop/orders/${route.params.id}/review`, { method: 'POST', headers: { Authorization: `Bearer ${authStore.token}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ rating: rating.value, content: reviewContent.value.trim() }) }); const result = await response.json(); if (!response.ok || result.code !== 0) throw new Error(result.message || '评价失败'); reviewVisible.value = false; showToast('评价成功'); await load() } catch (error) { showToast(error.message || '评价失败') } finally { reviewSubmitting.value = false } }
onMounted(load)
</script>
<template>
  <main class="order-detail-page"><van-nav-bar title="订单详情" left-arrow @click-left="router.back" /><van-loading v-if="loading" class="shop-loading" /><template v-else><section class="order-status-banner"><van-icon name="clock-o" /><div><b>订单{{ statusMap[data.order.status] || '状态未知' }}<van-tag v-if="data.reviewed" type="success" round>已评价</van-tag></b><small>{{ data.order.status === 1 ? '请耐心等待对方接单' : data.order.status === 2 ? '请享受专属服务，完成后请确认' : '订单已完成，感谢使用' }}</small></div></section><section class="order-detail-body"><div class="order-people"><span>♡</span><b>{{ data.order.buyerName || '我' }}（你）</b><i>♡</i><b>{{ data.order.sellerName || '绑定对象' }}</b></div><van-divider /><article v-for="item in data.items" :key="item.id" class="order-detail-item"><div class="order-detail-thumb" :style="item.coverUrl ? { backgroundImage: `url(${item.coverUrl})` } : {}">♡</div><div><b>{{ item.itemTitle }}</b><small>数量：{{ item.quantity }}</small></div><strong>¥{{ Number(item.subtotal || 0).toFixed(2) }}</strong></article><van-divider /><div class="order-summary"><p><span>支付金额</span><b>¥{{ Number(data.order.totalAmount || 0).toFixed(2) }}</b></p><p><span>支付方式</span><b>余额支付</b></p><p v-if="data.order.appointmentTime"><span>服务预约时间</span><b>{{ data.order.appointmentTime }}</b></p></div><van-divider /><h3>订单跟踪</h3><div class="order-track"><div v-for="track in data.tracks" :key="`${track.status}-${track.operateTime}`" :class="{ current: track.status === data.order.status }"><i></i><span><b>{{ track.title }}</b><small>{{ track.operateTime }}<br>{{ track.description }}</small></span></div></div><section v-if="data.review?.length" class="order-review"><h3>我的评价</h3><div class="reviewer-info"><span class="reviewer-avatar"><img v-if="data.review[0].reviewerAvatarUrl" :src="data.review[0].reviewerAvatarUrl" alt="评价人头像" /><span v-else>{{ (data.review[0].reviewerName || '匿').slice(0, 1) }}</span></span><b>{{ data.review[0].reviewerName || '匿名用户' }}</b></div><van-rate :model-value="data.review[0].rating" readonly color="#ff62aa" /><p>{{ data.review[0].content || '未填写评价内容' }}</p></section></section><div v-if="data.canAccept || data.canComplete || data.canReview === true || Number(data.canReview) === 1" class="order-detail-actions"><van-button v-if="data.canAccept" block round color="#ff62aa" :loading="completing" @click="accept">确认接单</van-button><van-button v-if="data.canComplete" block round color="#ff62aa" :loading="completing" @click="complete">确认服务完成</van-button><van-button v-if="data.canReview === true || Number(data.canReview) === 1" block round plain type="primary" @click="reviewVisible = true">去评价</van-button></div></template><div v-if="reviewVisible" class="review-overlay"><div class="review-dialog"><h2>评价本次服务</h2><p>请为绑定对象的服务打分</p><van-rate v-model="rating" color="#ff62aa" void-icon="star" /><van-field v-model="reviewContent" type="textarea" rows="4" maxlength="1000" show-word-limit placeholder="写下你的评价（可选）" /><div class="review-actions"><van-button round plain @click="skipReview">暂不评价</van-button><van-button round color="#ff62aa" :loading="reviewSubmitting" @click="submitReview">提交评价</van-button></div></div></div></main>
</template>



